import{H as e,M as t,U as n,nt as r,z as i}from"./chunks/framework.CrYumu29.js";import"./chunks/assets.Dc_xZx0z.js";var a=JSON.parse(`{"title":"Integrated Development Environments (IDEs)","description":"","frontmatter":{},"headers":[],"relativePath":"notes/08-ide.md","filePath":"notes/08-ide.md","lastUpdated":1767217025000}`),o={name:`notes/08-ide.md`};function s(t,a,o,s,c,l){return r(),e(`div`,null,[...a[0]||=[n(`<h1 id="integrated-development-environments-ides" tabindex="-1">Integrated Development Environments (IDEs) <a class="header-anchor" href="#integrated-development-environments-ides" aria-label="Permalink to “Integrated Development Environments (IDEs)”">​</a></h1><h2 id="using-visual-studio" tabindex="-1">Using Visual Studio <a class="header-anchor" href="#using-visual-studio" aria-label="Permalink to “Using Visual Studio”">​</a></h2><p>The full-version Visual Studio (not just Visual Studio Code) will greatly\xA0aid your development of C++ programs, like the final project. (Note that Visual Studio on Mac does not support C++, so this is just for Windows users.)</p><p>You can download and use <a href="https://visualstudio.microsoft.com/vs/community/" target="_blank" rel="noreferrer">Visual Studio Community Edition</a> for free. Knowing how to use Visual Studio is a great job skill!</p><p>Here is a 12-minute\xA0tutorial on how to use Visual Studio.</p>`,5),i(`div`,{class:`youtube`},[i(`div`,null,[i(`iframe`,{width:`853`,height:`480`,src:`https://www.youtube-nocookie.com/embed/qL8rVDsqoOo?rel=0`,frameborder:`0`,allowfullscreen:`allowfullscreen`})])],-1),n(`<p>When installing Visual Studio, select “Desktop development with C++” as shown in this figure.<br><img src="/csci-235/assets/VisualStudioInstallation1.CaVMwb-6.png" alt="Installation settings for Visual Studio"></p><p>Quick tips for Visual Studio:</p><ul><li>Select an Empty (C++) project to start a command-line program.</li><li>Use the built-in debugger (F5) to set breakpoints, watch variables, and step through code.</li><li>Use CMake projects if you want a cross-platform build setup.</li></ul><h2 id="xcode-for-macos" tabindex="-1">Xcode for macOS <a class="header-anchor" href="#xcode-for-macos" aria-label="Permalink to “Xcode for macOS”">​</a></h2><p>Although there is a macOS version of Visual Studio, it does not support C++ development. The default for macOS is Apple&#39;s <a href="https://developer.apple.com/documentation/xcode" target="_blank" rel="noreferrer">Xcode</a> and the clang toolchain.</p><p>Install:</p><ul><li>Xcode from the App Store (or the Command Line Tools: <code>xcode-select --install</code>)</li><li>Homebrew (<a href="https://brew.sh/" target="_blank" rel="noreferrer">https://brew.sh/</a>) to install additional tools (cmake, gdb/lldb, etc.)</li></ul><h2 id="what-students-should-learn-short-checklist" tabindex="-1">What students should learn (short checklist) <a class="header-anchor" href="#what-students-should-learn-short-checklist" aria-label="Permalink to “What students should learn (short checklist)”">​</a></h2><p>Whichever IDE you try, look up and try out the following task.</p><ul><li>Create and organize a small console C++ project</li><li>Build from the IDE and from the command line (g++/clang++/MSVC)</li><li>Use the debugger: set breakpoints, step, inspect variables</li></ul>`,10)]])}var c=t(o,[[`render`,s]]);export{a as __pageData,c as default};